# SPDX-License-Identifier: Apache-2.0
"""Stage taxonomy: map trace events to (engine stage, op class).

The taxonomy is defined in docs/03-stage-taxonomy.md. Both the CPU leg and the GPU
leg are aggregated through this module so the results are directly comparable.

Pure functions, no I/O: see test_stages.py.
"""

from __future__ import annotations

import re
from typing import NamedTuple

# ---------------------------------------------------------------------------
# Axis A: engine stage, from the Python frame that encloses the work.
# Order matters: first match wins, so keep the specific rules above the general.
# ---------------------------------------------------------------------------
FRAME_RULES: list[tuple[str, tuple[str, ...]]] = [
    # frontend
    ("frontend.detokenize", ("v1/engine/detokenizer.py", "tokenizer.decode")),
    ("frontend.tokenize", ("v1/engine/", "entrypoints/openai/", "entrypoints/llm.py")),
    # engine core
    ("engine.schedule", ("v1/core/sched/scheduler.py",)),
    ("engine.kv_cache", (
        "v1/core/kv_cache_manager.py",
        "v1/core/block_pool.py",
        "v1/core/kv_cache_utils.py",
        "v1/core/kv_cache_coordinator.py",
    )),
    # worker
    ("runner.prepare_inputs", (
        "v1/worker/gpu/model_runner.py",
        "v1/worker/cpu/attn_utils.py",
        "v1/worker/cpu/input_batch.py",
    )),
    ("sample", (
        "v1/worker/gpu/sample/",
        "v1/worker/cpu/sampler.py",
        "v1/sample/ops/",
        "layers/sampler.py",
    )),
    # model
    ("model.forward", (
        "model_executor/models/",
        "model_executor/layers/",
        "model_executor/kernels/",
    )),
]

# Frames that live in a file that also hosts scheduler work (update_from_output etc.)
POSTPROCESS_MARKERS = ("update_from_output", "_free_request", "_update_request_with_output")

# ---------------------------------------------------------------------------
# Axis B: op class, from ATen op name and (optionally) tensor shapes.
# ---------------------------------------------------------------------------
ATTENTION_MARKERS = (
    "cpu_attention_with_kv_cache",
    "paged_attention",
    "flash_fwd",
    "_efficient_attention",
    "triton_attention",
    "sdpa",
    "scaled_dot_product",
)
KV_WRITE_MARKERS = ("reshape_and_cache", "cache_kernels", "concat_and_cache")

# Qwen3-0.6B linear shapes -> sub-stage label. Unknown shapes fall back to
# "linear[KxN]" and show up as such in the report (never silently merged).
LINEAR_SHAPES: dict[tuple[int, int], str] = {
    (1024, 2048): "linear.qkv",
    (2048, 1024): "linear.o_proj",
    (1024, 6144): "linear.gate_up",
    (3072, 1024): "linear.down",
}


class Classified(NamedTuple):
    stage: str
    op_class: str


FRAME_RE = re.compile(r"^(?P<file>.*?\.py)(?:\((?P<line>\d+)\))?:? ?(?P<func>[\w.<>_]+)?$")


def parse_frame(name: str) -> tuple[str, str]:
    """Split a kineto python_function event name into (file, function)."""
    m = FRAME_RE.match(name)
    if not m:
        return name, ""
    return (m.group("file") or name), (m.group("func") or "")


def stage_for_frame(file: str, func: str) -> str:
    """Axis A for a single frame. Returns 'other' when nothing matches."""
    if "sched/scheduler.py" in file and func in POSTPROCESS_MARKERS:
        return "engine.postprocess"
    haystack = f"{file} {func}"
    for stage, markers in FRAME_RULES:
        if any(m in haystack for m in markers):
            return stage
    return "other"


def _dims_of(event_args: dict) -> list[list[int]] | None:
    dims = event_args.get("Input Dims")
    if not dims:
        return None
    return dims


def linear_shape(event_args: dict) -> tuple[int, int] | None:
    """(K, N) for an aten::linear / aten::mm / aten::addmm event, else None."""
    dims = _dims_of(event_args)
    if not dims or len(dims) < 2:
        return None
    try:
        in_dims, weight_dims = dims[0], dims[1]
        if not in_dims or not weight_dims:
            return None
        return int(in_dims[-1]), int(weight_dims[0])
    except (TypeError, IndexError, ValueError):
        return None


def op_class_for(name: str, event_args: dict | None = None, *, vocab_size: int | None = None) -> str:
    """Axis B for one event."""
    event_args = event_args or {}

    # Device kernels and CPU attention both arrive here by name.
    for marker in ATTENTION_MARKERS:
        if marker in name:
            return "attention.paged"
    for marker in KV_WRITE_MARKERS:
        if marker in name:
            return "attention.kv_write"

    if name.startswith(("aten::linear", "aten::mm", "aten::addmm", "aten::matmul", "gemm")):
        shape = linear_shape(event_args)
        if shape is not None:
            k, n = shape
            if vocab_size and n >= int(0.9 * vocab_size):
                return "linear.lm_head"
            return LINEAR_SHAPES.get((k, n), f"linear[{k}x{n}]")
        return "linear"

    if "norm" in name.lower():
        return "norm"
    if "rotary" in name or "apply_rotary" in name:
        return "rope"
    if name.startswith("aten::") and any(
        a in name for a in ("silu", "gelu", "sigmoid", "silu_and_mul", "swiglu")
    ):
        return "activation"
    if any(a in name for a in ("argmax", "softmax", "topk", "gumbel", "multinomial")):
        return "sampler"
    if name.startswith("aten::"):
        return "elementwise"
    return "python"


def classify(
    name: str,
    *,
    file: str = "",
    func: str = "",
    event_args: dict | None = None,
    vocab_size: int | None = None,
) -> Classified:
    """Full classification: engine stage + op class."""
    stage = stage_for_frame(file, func) if file else "other"
    op_class = op_class_for(name, event_args, vocab_size=vocab_size)
    if op_class == "linear.lm_head" and stage in ("model.forward", "other"):
        stage = "model.lm_head"
    return Classified(stage, op_class)

# SPDX-License-Identifier: Apache-2.0
"""Aggregate a torch/kineto trace into the stage taxonomy of docs/03-stage-taxonomy.md.

Works on CPU traces today; GPU traces are handled by correlating kernels back to the
CPU op that launched them (see docs/02-methodology.md#async-device-time).

Usage:
    analyze_trace.py --trace traces/cpu-int8-conc8/*.json.gz --out results/cpu-int8-conc8.csv
"""

from __future__ import annotations

import argparse
import bisect
import collections
import gzip
import json
import os
import sys

import stages

FRAME_CAT = "python_function"
KERNEL_CATS = {"kernel", "gpu_memcpy", "gpu_memset"}


def load(path: str) -> list[dict]:
    opener = gzip.open if path.endswith(".gz") else open
    with opener(path, "rt") as f:
        raw = json.load(f)
    events = raw["traceEvents"] if isinstance(raw, dict) else raw
    return events


def complete_events(events: list[dict]) -> list[dict]:
    return [e for e in events if e.get("ph") == "X" and e.get("dur")]


def self_times(events: list[dict]) -> dict[int, float]:
    """Self time per event id: duration minus the duration of direct children."""
    by_tid: dict[object, list[dict]] = collections.defaultdict(list)
    for e in events:
        by_tid[e.get("tid")].append(e)

    result: dict[int, float] = {}
    for evs in by_tid.values():
        evs.sort(key=lambda e: (e["ts"], -e["dur"]))
        stack: list[dict] = []
        for e in evs:
            e["_end"] = e["ts"] + e["dur"]
            e["_kids"] = 0.0
            while stack and stack[-1]["_end"] <= e["ts"]:
                top = stack.pop()
                if stack:
                    stack[-1]["_kids"] += top["dur"]
            stack.append(e)
        while stack:
            top = stack.pop()
            if stack:
                stack[-1]["_kids"] += top["dur"]
        for e in evs:
            result[id(e)] = max(e["dur"] - e["_kids"], 0.0)
    return result


class FrameIndex:
    """Innermost-enclosing python frame lookup, per thread."""

    def __init__(self, events: list[dict]):
        self._ts: dict[object, list[float]] = collections.defaultdict(list)
        self._frames: dict[object, list[tuple[float, float, str, str]]] = (
            collections.defaultdict(list)
        )
        for e in events:
            if e.get("cat") != FRAME_CAT:
                continue
            file, func = stages.parse_frame(e.get("name", ""))
            tid = e.get("tid")
            self._frames[tid].append((e["ts"], e["ts"] + e["dur"], file, func))
        for tid in self._frames:
            self._frames[tid].sort()
            self._ts[tid] = [f[0] for f in self._frames[tid]]

    def stage_at(self, tid, ts: float) -> str:
        frames = self._frames.get(tid)
        if not frames:
            return "other"
        i = bisect.bisect_right(self._ts[tid], ts) - 1
        while i >= 0:
            start, end, file, func = frames[i]
            if end >= ts:
                stage = stages.stage_for_frame(file, func)
                if stage != "other":
                    return stage
            i -= 1
        return "other"


def kernel_to_launcher(events: list[dict]) -> dict[int, dict]:
    """Map kernel event id -> the CPU runtime event that launched it (GPU traces)."""
    launchers: dict[str, dict] = {}
    for e in events:
        if e.get("cat") in ("cuda_runtime", "Runtime", "gpu_user_annotation"):
            corr = e.get("args", {}).get("correlation")
            if corr is not None:
                launchers[str(corr)] = e
    mapping: dict[int, dict] = {}
    for e in events:
        if e.get("cat") in KERNEL_CATS:
            corr = e.get("args", {}).get("correlation")
            if corr is not None and str(corr) in launchers:
                mapping[id(e)] = launchers[str(corr)]
    return mapping


def kind_of_trace(events: list[dict]) -> str:
    return "gpu" if any(e.get("cat") in KERNEL_CATS for e in events) else "cpu"


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--trace", required=True, nargs="+")
    ap.add_argument("--out", default=None, help="CSV path")
    ap.add_argument("--vocab-size", type=int, default=151936)
    ap.add_argument("--top", type=int, default=20)
    args = ap.parse_args()

    out_rows: list[dict] = []
    for path in args.trace:
        events = complete_events(load(path))
        if not events:
            print(f"skip {path}: no complete events", file=sys.stderr)
            continue

        st = self_times(events)
        frames = FrameIndex(events)
        kind = kind_of_trace(events)
        launcher = kernel_to_launcher(events) if kind == "gpu" else {}

        metric = "device_ms" if kind == "gpu" else "self_ms"
        width = (max(e["_end"] for e in events) - min(e["ts"] for e in events)) / 1000.0

        # (stage, op_class) -> [ms, calls]
        agg: dict[tuple[str, str], list[float]] = collections.defaultdict(lambda: [0.0, 0])
        by_op: collections.Counter = collections.Counter()

        for e in events:
            if kind == "gpu":
                if e.get("cat") not in KERNEL_CATS:
                    continue  # host spans are reported separately below
                host = launcher.get(id(e), e)
                tid, ts = host.get("tid"), host.get("ts", e["ts"])
            else:
                if e.get("cat") == FRAME_CAT:
                    tid, ts = e.get("tid"), e["ts"]
                elif e.get("cat") in ("cpu_op", "user_annotation"):
                    tid, ts = e.get("tid"), e["ts"]
                else:
                    continue

            stage = frames.stage_at(tid, ts)
            op_class = stages.op_class_for(
                e.get("name", ""), e.get("args"), vocab_size=args.vocab_size
            )
            if op_class == "linear.lm_head" and stage in ("model.forward", "other"):
                stage = "model.lm_head"
            ms = st.get(id(e), e["dur"]) / 1000.0
            agg[(stage, op_class)][0] += ms
            agg[(stage, op_class)][1] += 1
            by_op[e.get("name", "")] += ms

        total = sum(v[0] for v in agg.values()) or 1.0
        print(f"\n=== {os.path.basename(path)}  [{kind} trace, metric={metric}, "
              f"window={width:.1f} ms] ===")

        stage_totals = collections.Counter()
        for (stage, _), (ms, _n) in agg.items():
            stage_totals[stage] += ms

        print(f"\n-- stage ({metric}) --")
        for stage, ms in stage_totals.most_common():
            print(f"  {ms:9.2f} ms {100 * ms / total:5.1f}%  {stage}")
        other_pct = 100 * stage_totals["other"] / total
        if other_pct > 10:
            print(f"  !! 'other' is {other_pct:.1f}% — taxonomy needs updating")

        print(f"\n-- top {args.top} by {metric} --")
        for name, ms in by_op.most_common(args.top):
            print(f"  {ms:9.2f} ms {100 * ms / total:5.1f}%  {name[:100]}")

        print("\n-- (stage, op_class) --")
        for (stage, op_class), (ms, n) in sorted(
            agg.items(), key=lambda kv: -kv[1][0]
        )[: args.top]:
            print(f"  {ms:9.2f} ms {100 * ms / total:5.1f}%  {stage:22s} {op_class:16s} n={n}")

        for (stage, op_class), (ms, n) in agg.items():
            out_rows.append(
                {
                    "trace": os.path.basename(path),
                    "device": kind,
                    "metric": metric,
                    "stage": stage,
                    "op_class": op_class,
                    "ms": round(ms, 4),
                    "calls": n,
